<script setup lang="ts">
import SketchIcon from '../../components/SketchIcon.vue'
import { onMounted, reactive, ref, watch } from 'vue'
import { ElDialog } from 'element-plus'
import { useRoute } from 'vue-router'
import SiteShell from '../../components/SiteShell.vue'
import ContentState from '../../features/content/ContentState.vue'
import ContentPager from '../../features/content/ContentPager.vue'
import ProductSelector from '../../features/content/ProductSelector.vue'
import { deleteMedia, downloadFile, readFiles, readMedia, readProducts, replaceFile, saveRecord, setPublication, uploadFile, uploadMedia } from '../../features/content/api'
import { messageOf } from '../../features/content/presentation'
import { formatDate, formatSize, statusLabels, visibilityLabels, type ContentFile, type Media, type PageResult, type ProductChoice } from '../../features/content/types'
import '../../features/content/style.css'
const route = useRoute()
const tab = ref<'files' | 'media'>(route.query.tab === 'media' ? 'media' : 'files'), files = ref<PageResult<ContentFile> | null>(null), media = ref<PageResult<Media> | null>(null), products = ref<ProductChoice[]>([])
const loading = ref(true), error = ref(''), notice = ref(''), actionError = ref(''), saving = ref(false), keyword = ref(''), type = ref(''), status = ref(''), visibility = ref('')
const dialogOpen = ref(false), mode = ref<'create' | 'edit' | 'replace'>('create'), editing = ref<ContentFile | null>(null), chosenFile = ref<File | null>(null), saveError = ref(''), uploadInputKey = ref(0)
const mediaDialog = ref(false), altText = ref(''), mediaFile = ref<File | null>(null)
const confirmOpen = ref(false), pending = ref<{ kind: 'status'; item: ContentFile } | { kind: 'delete'; item: Media } | null>(null), confirmError = ref('')
const form = reactive({ title: '', type: '产品说明', versionNote: '', productIds: [] as string[], visibility: 'PUBLIC' as ContentFile['visibility'] })
let request = 0
async function load(page = 1) { const current = ++request; loading.value = true; error.value = ''; try { if (tab.value === 'files') { const result = await readFiles({ keyword: keyword.value, type: type.value, status: status.value, visibility: visibility.value, page, pageSize: 20 }, true); if (current === request) files.value = result } else { const result = await readMedia({ page, pageSize: 20 }); if (current === request) media.value = result } } catch (cause) { if (current === request) error.value = messageOf(cause) } finally { if (current === request) loading.value = false } }
function edit(item: ContentFile | null, nextMode: 'create' | 'edit' | 'replace' = 'create') { mode.value = nextMode; editing.value = item; chosenFile.value = null; uploadInputKey.value++; saveError.value = ''; Object.assign(form, item ? { title: item.title, type: item.type, versionNote: item.versionNote, productIds: [...item.productIds], visibility: item.visibility } : { title: '', type: '产品说明', versionNote: '', productIds: [], visibility: 'PUBLIC' }); if (nextMode === 'replace') form.versionNote = ''; dialogOpen.value = true }
function chooseFile(event: Event, image = false) { const item = (event.target as HTMLInputElement).files?.[0] ?? null; saveError.value = ''; if (image) mediaFile.value = item; else chosenFile.value = item }
async function save() {
  if (saving.value) return
  saving.value = true; saveError.value = ''; notice.value = ''
  try {
    if (mode.value !== 'edit' && !chosenFile.value) throw new Error('请先选择需要上传的 PDF 文件。')
    if (chosenFile.value && (chosenFile.value.size > 10 * 1024 * 1024 || !/\.pdf$/i.test(chosenFile.value.name))) throw new Error('请选择不超过 10 MB 的 PDF 文件。')
    if (mode.value === 'replace' && editing.value && chosenFile.value) await replaceFile(editing.value, chosenFile.value, form.versionNote)
    else if (mode.value === 'edit' && editing.value) await saveRecord('/admin/files', { ...form, expectedVersion: editing.value.version }, editing.value.id)
    else if (chosenFile.value) await uploadFile(chosenFile.value, form)
    notice.value = mode.value === 'create' ? 'PDF 已上传为草稿，发布后即可在下载中心访问。' : mode.value === 'replace' ? '文件已替换为新版本；旧下载地址已失效。' : '文件信息已保存。'
    dialogOpen.value = false; await load(files.value?.meta.page || 1)
  } catch (cause) { saveError.value = messageOf(cause) } finally { saving.value = false }
}
function newMedia() { mediaFile.value = null; altText.value = ''; saveError.value = ''; uploadInputKey.value++; mediaDialog.value = true }
async function saveMedia() { if (saving.value) return; saving.value = true; saveError.value = ''; notice.value = ''; try { if (!mediaFile.value) throw new Error('请先选择图片。'); if (mediaFile.value.size > 5 * 1024 * 1024 || !['image/jpeg', 'image/png', 'image/webp'].includes(mediaFile.value.type)) throw new Error('请选择不超过 5 MB 的 JPEG、PNG 或 WebP 图片。'); await uploadMedia(mediaFile.value, altText.value); notice.value = '图片已上传，可在文章、Banner 或品牌设置中选择使用。'; mediaDialog.value = false; await load() } catch (cause) { saveError.value = messageOf(cause) } finally { saving.value = false } }
function askStatus(item: ContentFile) { pending.value = { kind: 'status', item }; confirmError.value = ''; confirmOpen.value = true }
function askDelete(item: Media) { pending.value = { kind: 'delete', item }; confirmError.value = ''; confirmOpen.value = true }
async function confirm() { if (!pending.value || saving.value) return; saving.value = true; confirmError.value = ''; notice.value = ''; try { if (pending.value.kind === 'delete') { await deleteMedia(pending.value.item); notice.value = '图片已删除。' } else { const publish = pending.value.item.status !== 'PUBLISHED'; await setPublication('/admin/files', pending.value.item, publish); notice.value = `文件已${publish ? '发布' : '下线'}。` } confirmOpen.value = false; await load() } catch (cause) { confirmError.value = messageOf(cause) } finally { saving.value = false } }
async function download(item: ContentFile) { if (saving.value) return; saving.value = true; actionError.value = ''; try { await downloadFile(item); notice.value = '文件已准备下载，请查看浏览器下载记录。' } catch (cause) { actionError.value = messageOf(cause) } finally { saving.value = false } }
watch(tab, () => { actionError.value = ''; notice.value = ''; void load() })
onMounted(async () => { void load(); try { products.value = await readProducts(true) } catch { actionError.value = '商品选项加载失败，文件列表仍可使用。刷新页面可重试加载。' } })
</script>
<template><SiteShell title="文件与媒体" admin eyebrow="BRAND / LIBRARY"><div class="content-admin-intro"><div><p>为每一份资料，留好来处。</p><span>发布 PDF 资料，维护图片素材，让内容更新有序发生。</span></div><RouterLink to="/downloads" class="secondary-button">查看下载中心 ↗</RouterLink></div><div class="content-tabs" role="tablist" aria-label="资源类型"><button id="files-tab" type="button" role="tab" :aria-selected="tab === 'files'" aria-controls="resource-panel" @click="tab = 'files'"><SketchIcon name="orders" :size="21" />PDF 资料</button><button id="media-tab" type="button" role="tab" :aria-selected="tab === 'media'" aria-controls="resource-panel" @click="tab = 'media'"><SketchIcon name="grid" :size="21" />图片媒体库</button></div><p v-if="notice" class="content-success" role="status">{{ notice }}</p><p v-if="actionError" class="error-summary" role="alert">{{ actionError }}</p><div id="resource-panel" role="tabpanel" :aria-labelledby="`${tab}-tab`"><template v-if="tab === 'files'"><form class="content-admin-filter" @submit.prevent="load(1)"><label>资料关键词<input v-model="keyword" type="search" class="wm-search-input" placeholder="输入资料名称" maxlength="100" /></label><label>类型<input v-model="type" placeholder="全部类型" maxlength="50" /></label><label>发布状态<select v-model="status"><option value="">全部状态</option><option v-for="(label, key) in statusLabels" :key="key" :value="key">{{ label }}</option></select></label><label>可见范围<select v-model="visibility"><option value="">全部范围</option><option v-for="(label, key) in visibilityLabels" :key="key" :value="key">{{ label }}</option></select></label><button type="submit" class="secondary-button">查询</button><button type="button" class="primary-button" @click="edit(null)"><SketchIcon name="plus" :size="20" />上传 PDF</button></form><ContentState :loading="loading" :error="error" :empty="!files?.items.length" empty-title="资料库还是空的" empty-note="上传一份产品说明、安全指南或其他 PDF 资料。" @retry="load()"><div class="table-wrap"><table class="content-admin-table"><thead><tr><th>文件</th><th>类型 / 范围</th><th>状态</th><th>最近更新</th><th>操作</th></tr></thead><tbody><tr v-for="file in files?.items" :key="file.id"><td><strong>{{ file.title }}</strong><span>{{ file.filename }} · {{ formatSize(file.sizeBytes) }}</span><span>{{ file.versionNote }}</span></td><td>{{ file.type }}<span>{{ visibilityLabels[file.visibility] }}</span></td><td><span class="content-status" :data-status="file.status">{{ statusLabels[file.status] }}</span></td><td>{{ formatDate(file.updatedAt) }}</td><td><div class="content-row-actions"><button type="button" class="row-link" @click="edit(file, 'edit')">编辑</button><button type="button" class="row-link" @click="edit(file, 'replace')">替换</button><button type="button" class="row-link" :disabled="saving || file.status !== 'PUBLISHED'" :title="file.status !== 'PUBLISHED' ? '发布后可下载' : '下载 PDF'" @click="download(file)">下载</button><button type="button" class="row-link" @click="askStatus(file)">{{ file.status === 'PUBLISHED' ? '下线' : '发布' }}</button></div></td></tr></tbody></table></div><ContentPager v-if="files" :meta="files.meta" @change="load" /></ContentState></template><template v-else><div class="content-section-title"><p class="content-note">JPEG、PNG、WebP 图片；单张不超过 5 MB。被内容引用的图片需解除引用后才能删除。</p><button type="button" class="primary-button" @click="newMedia"><SketchIcon name="plus" :size="20" />上传图片</button></div><ContentState :loading="loading" :error="error" :empty="!media?.items.length" empty-title="给故事准备一点画面" empty-note="上传图片后，可在文章、Banner 和品牌设置中使用。" @retry="load()"><div class="content-media-grid"><article v-for="image in media?.items" :key="image.id"><img :src="image.url" :alt="image.altText || image.filename" loading="lazy" /><div><h2>{{ image.altText || image.filename }}</h2><p>{{ image.width }} × {{ image.height }} · {{ formatSize(image.sizeBytes) }}</p><small>{{ image.referenceCount }} 处引用 · {{ image.publicReferenceCount }} 处公开使用</small><label class="content-media-id">媒体 ID（商品关联）<input :value="image.id" readonly :aria-label="`${image.altText || image.filename}的媒体 ID`" @focus="($event.target as HTMLInputElement).select()" /></label><button class="row-link" type="button" :disabled="image.referenceCount > 0" :title="image.referenceCount > 0 ? '请先在相关内容中解除引用' : '删除图片'" @click="askDelete(image)"><SketchIcon v-if="image.referenceCount === 0" name="trash" :size="18" />{{ image.referenceCount > 0 ? '使用中' : '删除图片' }}</button></div></article></div><ContentPager v-if="media" :meta="media.meta" @change="load" /></ContentState></template></div>
<ElDialog v-model="dialogOpen" :title="mode === 'create' ? '上传 PDF 资料' : mode === 'edit' ? '编辑资料信息' : '替换 PDF 文件'" width="min(720px, 94vw)" :show-close="!saving" :close-on-click-modal="!saving" :close-on-press-escape="!saving"><form class="content-form" @submit.prevent="save"><p v-if="saveError" class="error-summary wide" role="alert">{{ saveError }}</p><label v-if="mode !== 'edit'" class="wide content-upload-field">{{ mode === 'replace' ? '新版本 PDF' : '选择 PDF 文件' }}<input :key="uploadInputKey" type="file" accept="application/pdf,.pdf" required @change="chooseFile($event)" /><small>仅限 PDF，单个文件不超过 10 MB。</small></label><p v-if="mode === 'replace'" class="content-note wide">正在替换“{{ editing?.title }}”。替换成功后将生成新下载地址，原有链接失效。</p><template v-if="mode !== 'replace'"><label class="wide">资料名称<input v-model="form.title" required minlength="2" maxlength="100" /></label><label>资料类型<input v-model="form.type" required maxlength="50" placeholder="例如：产品说明" /></label><label>可见范围<select v-model="form.visibility"><option v-for="(label, key) in visibilityLabels" :key="key" :value="key">{{ label }}</option></select></label><ProductSelector v-model="form.productIds" :products="products" class="wide" /></template><label class="wide">{{ mode === 'replace' ? '本次更新说明' : '版本说明' }}<textarea v-model="form.versionNote" rows="3" required maxlength="500" placeholder="例如：v1.1 · 更新安装步骤" /></label><div class="content-form-actions wide"><button class="secondary-button" type="button" :disabled="saving" @click="dialogOpen = false">取消</button><button class="primary-button" type="submit" :disabled="saving">{{ saving ? '正在保存…' : mode === 'create' ? '上传为草稿' : mode === 'replace' ? '保存新版本' : '保存修改' }}</button></div></form></ElDialog>
<ElDialog v-model="mediaDialog" title="上传图片" width="min(520px, 94vw)" :show-close="!saving" :close-on-click-modal="!saving" :close-on-press-escape="!saving"><form class="content-form" @submit.prevent="saveMedia"><p v-if="saveError" class="error-summary wide" role="alert">{{ saveError }}</p><label class="wide content-upload-field">选择图片<input :key="uploadInputKey" type="file" accept="image/jpeg,image/png,image/webp" required @change="chooseFile($event, true)" /><small>支持 JPEG、PNG、WebP，单张不超过 5 MB。</small></label><label class="wide">图片说明<input v-model="altText" maxlength="200" placeholder="描述图片内容，便于识别与无障碍阅读" /></label><div class="wide content-form-actions"><button class="secondary-button" type="button" :disabled="saving" @click="mediaDialog = false">取消</button><button class="primary-button" type="submit" :disabled="saving">{{ saving ? '正在上传…' : '上传图片' }}</button></div></form></ElDialog>
<ElDialog v-model="confirmOpen" :title="pending?.kind === 'delete' ? '删除图片' : pending?.item.status === 'PUBLISHED' ? '下线资料' : '发布资料'" width="min(480px, 94vw)" :show-close="!saving" :close-on-click-modal="!saving" :close-on-press-escape="!saving"><template v-if="pending"><p v-if="pending.kind === 'delete'">确定删除“{{ pending.item.altText || pending.item.filename }}”？删除后需要重新上传才能使用。</p><p v-else>{{ pending.item.status === 'PUBLISHED' ? '下线后，下载中心将隐藏这份资料，原有下载地址也将停止访问。' : `发布后，这份资料将对“${visibilityLabels[pending.item.visibility]}”开放。` }}</p></template><p v-if="confirmError" class="error-summary" role="alert">{{ confirmError }}</p><template #footer><div class="content-form-actions"><button type="button" class="secondary-button" :disabled="saving" @click="confirmOpen = false">取消</button><button type="button" class="primary-button" :disabled="saving" @click="confirm">{{ saving ? '正在处理…' : '确认' }}</button></div></template></ElDialog></SiteShell></template>
